local function readSmallFile(path)
    if not path then return nil end
    local ok, content = pcall(function()
        local f = File(path)
        if not f.exists() then return nil end
        local fis = FileInputStream(f)
        local reader = BufferedReader(InputStreamReader(fis))
        local line = reader.readLine()
        reader.close(); fis.close()
        return line
    end)
    if ok then return content end
    return nil
end
local function writeSmallFile(path, text)
    if not path then return end
    pcall(function()
        local parent = File(path).getParentFile()
        if parent and not parent.exists() then parent.mkdirs() end
        local outputStream = FileOutputStream(File(path))
        local writer = OutputStreamWriter(outputStream)
        writer.write(tostring(text))
        writer.close(); outputStream.close()
    end)
end
local function deleteSmallFile(path) if not path then return end; pcall(function() File(path).delete() end) end

