-- Multi-signal device fingerprint: combines ANDROID_ID with the
-- device model/board and a random token generated once and saved
-- to private storage on first run. ANDROID_ID alone can be reset on
-- some rooted devices/custom ROMs; requiring all of these signals
-- together to match makes that kind of spoofing require changing
-- several independent things at once, not just one value.
local function getOrCreateInstallToken()
    local tokenPath = getPrivateDir() .. "/.mk_install_token.dat"
    local existing = readSmallFile(tokenPath)
    if existing and existing ~= "" then return existing end
    math.randomseed(os.time() + os.clock() * 1000000)
    local parts = {}
    for i = 1, 8 do parts[i] = string.format("%02X", math.random(0, 255)) end
    local token = table.concat(parts)
    writeSmallFile(tokenPath, token)
    return token
end
local function getDeviceId()
    local ok, id = pcall(function()
        local androidId = tostring(Settings.Secure.getString(service.getContentResolver(), Settings.Secure.ANDROID_ID))
        local model = tostring(Build.MODEL or "")
        local board = tostring(Build.BOARD or "")
        local installToken = getOrCreateInstallToken()
        local combined = androidId .. "|" .. model .. "|" .. board .. "|" .. installToken
        local fp = string.format("%04X%04X", _chk(combined), _chk(combined .. combined))
        return fp .. "-" .. androidId:sub(1, 6)
    end)
    if ok and id and id ~= "" then return id end
    return "unknown-device"
end

local function parseExpiryDate(dateStr)
    if not dateStr or dateStr == "" then return nil end
    local y, m, d = dateStr:match("^(%d+)-(%d+)-(%d+)$")
    if not y then return nil end
    local ok, t = pcall(function() return os.time({year = tonumber(y), month = tonumber(m), day = tonumber(d), hour = 23, min = 59}) end)
    if ok then return t end
    return nil
end

-- Percent-encodes a value before it's inserted into a Firebase REST
-- URL path, so a key containing '/', '?', '#', or similar cannot be
-- misread as extra path segments.
local function urlEncodeSegment(s)
    return (tostring(s):gsub("[^%w%-%_%.~]", function(c) return string.format("%%%02X", c:byte()) end))
end

local function fetchAndCheckKey(enteredKey)
    local deviceId = getDeviceId()
    local ok, body = pcall(function()
        local url = URL(FIREBASE_URL .. "/keys/" .. urlEncodeSegment(enteredKey) .. ".json")
        local conn = url.openConnection()
        conn.setRequestMethod("GET")
        conn.setConnectTimeout(8000); conn.setReadTimeout(8000)
        local code = conn.getResponseCode()
        if code ~= 200 then return nil end
        local reader = BufferedReader(InputStreamReader(conn.getInputStream()))
        local b = ""
        local line = reader.readLine()
        while line do b = b .. tostring(line); line = reader.readLine() end
        reader.close()
        return b:gsub("^%s+", ""):gsub("%s+$", "")
    end)
    if not ok then return "offline", nil, nil end
    if body == nil or body == "null" then return "invalid", nil, nil end

    local name = body:match('"name"%s*:%s*"(.-)"')
    local expiryStr = body:match('"expiry"%s*:%s*"(.-)"')

    -- Soft kill-switch: setting {"disabled": true} on a key (via the
    -- Manage Key screen's Disable button) blocks it immediately without
    -- deleting the record, so it can be re-enabled later if needed.
    local disabledFlag = body:match('"disabled"%s*:%s*true')
    if disabledFlag then return "disabled", name, nil end

    local expiryTs = parseExpiryDate(expiryStr)
    if expiryTs and os.time() > expiryTs then return "expired", name, nil end

    if MAX_DEVICES > 0 then
        -- New keys store an object of allowed devices: "devices": {"<id>": true, ...}
        -- Older keys created before this feature only had a single
        -- "device" string - that's still honoured as one occupied slot.
        local devicesBlock = body:match('"devices"%s*:%s*(%b{})')
        local legacyDevice = body:match('"device"%s*:%s*"(.-)"')
        local isMember, count = false, 0
        if devicesBlock then
            for devKey in devicesBlock:gmatch('"([^"]+)"%s*:%s*true') do
                count = count + 1
                if devKey == deviceId then isMember = true end
            end
        elseif legacyDevice and legacyDevice ~= "" then
            count = 1
            if legacyDevice == deviceId then isMember = true end
        end

        if isMember then
            return "ok", name, expiryTs
        elseif count < MAX_DEVICES then
            local assignOk = pcall(function()
                local url2 = URL(FIREBASE_URL .. "/keys/" .. urlEncodeSegment(enteredKey) .. "/devices/" .. urlEncodeSegment(deviceId) .. ".json")
                local conn2 = url2.openConnection()
                conn2.setRequestMethod("PUT")
                conn2.setDoOutput(true)
                conn2.setConnectTimeout(8000); conn2.setReadTimeout(8000)
                local writer = OutputStreamWriter(conn2.getOutputStream())
                writer.write("true")
                writer.flush(); writer.close()
                return conn2.getResponseCode() == 200
            end)
            if not assignOk then return "offline", name, nil end
            return "ok", name, expiryTs
        else
            return "device_mismatch", name, nil
        end
    end

    return "ok", name, expiryTs
end

local function daysBetween(t1, t2) return math.floor((t2 - t1) / 86400) end

-- Clock-tamper guard: returns the LARGER of the real current time and
-- the highest time this plugin has ever observed on this device.
-- Rolling the device clock backward can never decrease this value,
-- so trial/grace calculations based on it can't be extended just by
-- setting the date back. It cannot stop someone rolling the clock
-- back BEFORE the very first run (nothing has been observed yet to
-- compare against), but it closes the common case of rolling the
-- clock back after starting a trial or after the license was last
-- verified online.
local function getGuardedNow()
    local now = os.time()
    local maxSeen = tonumber(readSmallFile(MAX_SEEN_FILE) or "0") or 0
    local maxSeenPublic = tonumber(readSmallFile(PUBLIC_MAX_SEEN_FILE) or "0") or 0
    local guarded = math.max(now, maxSeen, maxSeenPublic)
    if guarded ~= maxSeen then writeSmallFile(MAX_SEEN_FILE, tostring(guarded)) end
    if guarded ~= maxSeenPublic then writeSmallFile(PUBLIC_MAX_SEEN_FILE, tostring(guarded)) end
    return guarded
end

-- Lets the customer know their license is about to expire, without a
-- full status screen (this plugin has no menu of its own - it only
-- runs when invoked - so a one-line reminder is the practical option
-- here). Shown at most once per calendar day, only in the last 7
-- days before expiry.
local function maybeShowExpiryReminder(expiryTs)
    if not expiryTs then return end
    local daysLeft = daysBetween(getGuardedNow(), expiryTs)
    if daysLeft < 0 or daysLeft > 7 then return end
    local reminderFile = _privateDir and (_privateDir .. "/.mk_last_reminder_" .. PLUGIN_ID .. ".dat") or nil
    if not reminderFile then return end
    local today = os.date("%Y-%m-%d", getGuardedNow())
    if readSmallFile(reminderFile) == today then return end
    writeSmallFile(reminderFile, today)
    local dayWord = (daysLeft == 1) and "day" or "days"
    Toast.makeText(service, "Your license expires in " .. tostring(daysLeft) .. " " .. dayWord .. ". Please renew soon.", Toast.LENGTH_LONG).show()
end

local function showLicenseDialog(prefillMessage)
    local welcomeText = DEFAULT_KEY ~= "" and "This app is currently free to use! Your key is already filled in below - just tap Activate." or "Please enter your license key below."
    local lay = {
        LinearLayout, orientation = "vertical", layout_width = "fill", layout_height = "wrap", padding = "16dp",
        {TextView, id = "welcomeTv", text = welcomeText, layout_width = "wrap_content", layout_height = "wrap_content"},
        {TextView, text = "License Key:", layout_width = "wrap_content", layout_height = "wrap_content", layout_marginTop = "10dp"},
        {EditText, id = "licenseInput", text = DEFAULT_KEY, hint = "XXXX-XXXX-XXXX-XXXX", layout_width = "fill", layout_height = "wrap_content"}
    }
    local dlg = LuaDialog(service)
    dlg.setTitle(PRODUCT_NAME ~= "" and ("Welcome to " .. PRODUCT_NAME) or "Welcome!")
    dlg.setView(loadlayout(lay))
    if prefillMessage then Toast.makeText(service, prefillMessage, Toast.LENGTH_LONG).show() end
    if BUY_LINK_URL ~= "" then
        dlg.setButton3("Get a License Key", function()
            local ok = pcall(function()
                local intent = Intent(Intent.ACTION_VIEW)
                intent.setData(Uri.parse(BUY_LINK_URL))
                intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                this.startActivity(intent)
            end)
            if not ok then Toast.makeText(service, "Could not open the link.", Toast.LENGTH_SHORT).show() end
        end)
    end
    dlg.setButton("Activate", function()
        local enteredKey = tostring(licenseInput.text):gsub('^%s+', ''):gsub('%s+$', '')
        if enteredKey == "" then Toast.makeText(service, "Please enter a key.", Toast.LENGTH_SHORT).show(); return end

        -- Simple brute-force cooldown: 5 wrong tries, then a 60s wait.
        local COOLDOWN_SECONDS, MAX_ATTEMPTS = 60, 5
        local failData = readSmallFile(FAILCOUNT_FILE) or ""
        local failCountStr, lastFailStr = failData:match("^(%d+)|(%d+)$")
        local failCount = tonumber(failCountStr) or 0
        local lastFailTime = tonumber(lastFailStr) or 0
        local sinceLastFail = os.time() - lastFailTime
        if failCount >= MAX_ATTEMPTS and sinceLastFail < COOLDOWN_SECONDS then
            local waitLeft = COOLDOWN_SECONDS - sinceLastFail
            Toast.makeText(service, "Too many attempts. Please wait " .. tostring(waitLeft) .. " seconds and try again.", Toast.LENGTH_LONG).show()
            return
        elseif failCount >= MAX_ATTEMPTS then
            failCount = 0 -- cooldown window has passed, allow trying again
        end

        Toast.makeText(service, "Checking license, please wait...", Toast.LENGTH_SHORT).show()
        local status, name, expiryTs = fetchAndCheckKey(enteredKey)
        if status == "ok" then
            writeSmallFile(FAILCOUNT_FILE, "0|0")
            writeLicenseKey(enteredKey)
            writeSmallFile(LASTOK_FILE, tostring(getGuardedNow()))
            dlg.dismiss()
            Toast.makeText(service, "Welcome, " .. tostring(name or "Customer") .. "!", Toast.LENGTH_SHORT).show()
            maybeShowExpiryReminder(expiryTs)
            runProtectedCode()
        elseif status == "offline" then
            -- Not a wrong-guess attempt, so this does not count toward the cooldown.
            Toast.makeText(service, "Could not reach the license server. Check your internet connection.", Toast.LENGTH_LONG).show()
        else
            failCount = failCount + 1
            writeSmallFile(FAILCOUNT_FILE, tostring(failCount) .. "|" .. tostring(os.time()))
            if status == "expired" then
                Toast.makeText(service, "This license key has expired. Please contact the seller to renew.", Toast.LENGTH_LONG).show()
            elseif status == "device_mismatch" then
                Toast.makeText(service, "This key has reached its device limit on other device(s).", Toast.LENGTH_LONG).show()
            elseif status == "disabled" then
                Toast.makeText(service, "This license key has been disabled by the seller.", Toast.LENGTH_LONG).show()
            else
                Toast.makeText(service, "That key was not recognised. Please check it and try again.", Toast.LENGTH_LONG).show()
            end
        end
    end)
    dlg.setButton2("Cancel", function() dlg.dismiss() end)
    dlg.setCancelable(false)
    dlg.show()
end

local function startup()
    local storedKey = readLicenseKey()
    if storedKey then
        local status, name, expiryTs = fetchAndCheckKey(storedKey)
        if status == "ok" then
            writeSmallFile(LASTOK_FILE, tostring(getGuardedNow()))
            maybeShowExpiryReminder(expiryTs)
            runProtectedCode(); return
        elseif status == "offline" then
            local lastOk = tonumber(readSmallFile(LASTOK_FILE) or "0") or 0
            if lastOk > 0 and daysBetween(lastOk, getGuardedNow()) <= GRACE_DAYS then
                runProtectedCode(); return
            else
                showLicenseDialog("Couldn't reach the license server and the offline grace period has ended. Please connect to the internet and re-enter your key.")
                return
            end
        elseif status == "disabled" then
            deleteSmallFile(LICENSE_FILE)
            showLicenseDialog("This license key has been disabled by the seller. Please contact them for help."); return
        else
            deleteSmallFile(LICENSE_FILE)
            local msg = "Thank you for using " .. (PRODUCT_NAME ~= "" and PRODUCT_NAME or "this app") .. "! Please get a new license key to continue, or contact the seller for help."
            if status == "expired" then msg = "Your license has expired. Please contact the seller to renew." end
            if status == "device_mismatch" then msg = "This key has reached its device limit on other device(s)." end
            showLicenseDialog(msg); return
        end
    end

    if TRIAL_DAYS > 0 then
        local trialStartPrivate = tonumber(readSmallFile(TRIAL_FILE) or "")
        local trialStartPublic = tonumber(readSmallFile(PUBLIC_TRIAL_FILE) or "")
        local trialStart
        if trialStartPrivate and trialStartPublic then
            trialStart = math.min(trialStartPrivate, trialStartPublic)
        else
            trialStart = trialStartPrivate or trialStartPublic or getGuardedNow()
        end
        writeSmallFile(TRIAL_FILE, tostring(trialStart))
        writeSmallFile(PUBLIC_TRIAL_FILE, tostring(trialStart))
        local elapsed = daysBetween(trialStart, getGuardedNow())
        if elapsed <= TRIAL_DAYS then runProtectedCode(); return
        else showLicenseDialog("Your free trial has ended. Please enter a license key to continue."); return end
    end

    showLicenseDialog(nil)
end

startup()

return true
